const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isLetter = (ch) => ch !== undefined && /[A-Za-z]/.test(ch)
const isDigit = (ch) => ch !== undefined && /[0-9]/.test(ch)
const isHexDigit = (ch) => ch !== undefined && /[0-9a-fA-F]/.test(ch)
const isBinDigit = (ch) => ch === '0' || ch === '1'
const isOctDigit = (ch) => ch !== undefined && /[0-7]/.test(ch)
const isIdentPart = (ch) => ch !== undefined && (/[A-Za-z0-9_]/.test(ch))

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

class Scanner {
  constructor(source) {
    this.cps = Array.from(source)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.cps[this.i + offset]
  }

  eof(offset = 0) {
    return this.i + offset >= this.cps.length
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  next() {
    const c = this.cps[this.i++]
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col += 1
    }
    return c
  }

