  // between two digits of the run. Returns the consumed text, or null if
  // no digit was present to start the run.
  readDigitRun(isDigit) {
    if (!isDigit(this.peek())) return null
    let s = this.next()
    for (;;) {
      if (isDigit(this.peek())) {
        s += this.next()
      } else if (this.peek() === '_' && isDigit(this.peek(1))) {
        s += this.next()
        s += this.next()
      } else {
        break
      }
    }
    return s
  }

  scanIdentifier() {
    const start = this.pos()
    let s = this.next()
    while (isIdentPart(this.peek())) s += this.next()
    const kind = KEYWORDS.has(s) ? 'keyword' : 'ident'
    return { kind, raw: s, line: start.line, col: start.col }
  }

  scanNumber() {
    const start = this.pos()
    let text = ''
    let valid = true

    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X' || this.peek(1) === 'b' || this.peek(1) === 'B' || this.peek(1) === 'o' || this.peek(1) === 'O')) {
      text += this.next() // '0'
      const pfx = this.next()
      text += pfx
      const pred = pfx === 'x' || pfx === 'X' ? isHexDigit : pfx === 'b' || pfx === 'B' ? isBinDigit : isOctDigit
      const digits = this.readDigitRun(pred)
      if (digits === null) {
        valid = false
      } else {
        text += digits
      }
    } else {
      const intPart = this.readDigitRun(isDigit)
      text += intPart

      if (this.peek() === '.' && isDigit(this.peek(1))) {
        text += this.next() // '.'
        text += this.readDigitRun(isDigit)
      }

      if (this.peek() === 'e' || this.peek() === 'E') {
        const c1 = this.peek(1)
        const isSign = c1 === '+' || c1 === '-'
        const followsDigit = isDigit(c1) || (isSign && isDigit(this.peek(2)))
        if (followsDigit) {
          text += this.next() // e/E
          if (this.peek() === '+' || this.peek() === '-') text += this.next()
          text += this.readDigitRun(isDigit)
        }
      }
    }

    if (valid && isIdentPart(this.peek())) valid = false

    if (!valid) {
      while (isIdentPart(this.peek())) text += this.next()
      throw new LexError(start.line, start.col, `invalid number ${text}`)
    }

