    const start = this.pos()
    this.next() // opening quote
    let value = ''
    for (;;) {
      if (this.eof()) throw new LexError(start.line, start.col, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.next()
        break
      }
      if (ch === '\n') {
        const p = this.pos()
        throw new LexError(p.line, p.col, 'newline in string')
      }
