        const bpos = this.pos()
        this.next() // backslash
        if (this.eof()) throw new LexError(start.line, start.col, 'unterminated string')
        const ech = this.peek()
        if (ech === 'n') {
          value += '\n'
          this.next()
        } else if (ech === 't') {
          value += '\t'
          this.next()
        } else if (ech === 'r') {
          value += '\r'
          this.next()
        } else if (ech === '\\') {
          value += '\\'
          this.next()
        } else if (ech === '"') {
          value += '"'
          this.next()
        } else if (ech === '0') {
          value += '\0'
          this.next()
        } else if (ech === 'x') {
          this.next() // x
          const h0 = this.peek()
          const h1 = this.peek(1)
          if (isHexDigit(h0) && isHexDigit(h1)) {
            this.next()
            this.next()
            value += String.fromCharCode(parseInt(h0 + h1, 16))
          } else {
