        } else {
          throw new LexError(bpos.line, bpos.col, `invalid escape \\${ech}`)
        }
      } else {
        value += ch
        this.next()
      }
    }
    return { kind: 'string', value, line: start.line, col: start.col }
  }

  scanRawString() {
    const start = this.pos()
    this.next() // 'r'
    this.next() // '"'
    let value = ''
    for (;;) {
      if (this.eof()) throw new LexError(start.line, start.col, 'unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.next()
        break
      }
      value += ch
      this.next()
    }
    return { kind: 'rawstring', value, line: start.line, col: start.col }
  }

  scanPunct() {
    const start = this.pos()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.includes(two)) {
      this.next()
      this.next()
      return { kind: 'punct', raw: two, line: start.line, col: start.col }
    }
    const one = this.peek()
    if (ONE_CHAR_PUNCT.has(one)) {
      this.next()
      return { kind: 'punct', raw: one, line: start.line, col: start.col }
    }
    throw new LexError(start.line, start.col, `unexpected character ${one}`)
  }

  skipWhitespaceAndComments() {
    for (;;) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.next()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.next()
        this.next()
        while (!this.eof() && this.peek() !== '\n') this.next()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const start = this.pos()
        this.next()
        this.next()
        let depth = 1
        while (depth > 0) {
          if (this.eof()) throw new LexError(start.line, start.col, 'unterminated block comment')
          const ch = this.next()
          if (ch === '/' && this.peek() === '*') {
            this.next()
            depth += 1
          } else if (ch === '*' && this.peek() === '/') {
            this.next()
            depth -= 1
          }
        }
        continue
      }
      break
    }
  }

  nextToken() {
    this.skipWhitespaceAndComments()
    if (this.eof()) return null

    const c = this.peek()
    if (c === 'r' && this.peek(1) === '"') return this.scanRawString()
    if (isLetter(c) || c === '_') return this.scanIdentifier()
    if (isDigit(c)) return this.scanNumber()
    if (c === '"') return this.scanString()
    return this.scanPunct()
  }
}

