import { tokenize, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function bodyOf(tok) {
  if (tok.kind === 'string' || tok.kind === 'rawstring') return JSON.stringify(tok.value)
  return tok.raw
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = await readStdin()

  let tokens
  try {
    tokens = tokenize(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out = ''
  if (mode === 'tokens') {
    for (const tok of tokens) {
      out += `${tok.line}:${tok.col} ${tok.kind} ${bodyOf(tok)}\n`
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const tok of tokens) counts[tok.kind] += 1
    for (const k of STAT_KINDS) out += `${k} ${counts[k]}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

